import { CustomTooltip } from 'components/CustomTooltip';
import { Icon, Info } from 'components/icon';
import { StyledTooltip } from 'shared/Styles';

import { DrillDownColumnGroup } from '../../DrillDownTable.types';
import {
  DDTAxisHeader,
  DDTAxisHeaderBottom,
  DDTAxisHeaderTop,
  DDTGroupHeader,
  DDTGroupsWrapper,
  DDTGroupTitle,
  DDTGroupTitleUnit,
  DDTHeaderRow,
  DDTInfoIconWrapper,
  DDTSubColumnHeader,
  DDTSubColumnsRow,
} from './DrillDownTableHeader.styles';

interface InfoIconProps {
  readonly tooltip?: string;
}

function InfoIcon({ tooltip }: InfoIconProps): React.ReactElement | null {
  if (!tooltip) return null;
  return (
    <CustomTooltip
      content={<StyledTooltip size="small">{tooltip}</StyledTooltip>}
    >
      <DDTInfoIconWrapper>
        <Icon icon={Info} size="small" />
      </DDTInfoIconWrapper>
    </CustomTooltip>
  );
}

export interface DrillDownTableHeaderProps {
  readonly columnGroups: DrillDownColumnGroup[];
  readonly axisWidth: string;
  readonly axisTitle: string;
  readonly dataTestId?: string;
}

export const DrillDownTableHeader: React.FC<DrillDownTableHeaderProps> = ({
  columnGroups,
  axisWidth,
  axisTitle,
  dataTestId,
}) => {
  const testId = (suffix: string) =>
    dataTestId ? `${dataTestId}-${suffix}` : undefined;

  const axisWidthStyle = {
    '--ddt-axis-width': axisWidth,
  } as React.CSSProperties;

  return (
    <DDTHeaderRow role="rowgroup" data-testid={testId('header')}>
      <DDTAxisHeader
        style={axisWidthStyle}
        role="columnheader"
        aria-label={axisTitle}
      >
        <DDTAxisHeaderTop />
        <DDTAxisHeaderBottom data-testid={testId('axis-header')}>
          {axisTitle}
        </DDTAxisHeaderBottom>
      </DDTAxisHeader>

      <DDTGroupsWrapper>
        {columnGroups.map((group, gIdx) => {
          const isLastGroup = gIdx === columnGroups.length - 1;
          return (
            <DDTGroupHeader
              key={group.id}
              isLast={isLastGroup}
              role="columnheader"
              data-testid={testId(`group-header-${group.id}`)}
            >
              <DDTGroupTitle>
                {group.title}
                {group.unit && (
                  <DDTGroupTitleUnit>{group.unit}</DDTGroupTitleUnit>
                )}
                <InfoIcon tooltip={group.tooltipContent} />
              </DDTGroupTitle>

              <DDTSubColumnsRow>
                {group.columns.map((col, cIdx) => {
                  const isLastCol = cIdx === group.columns.length - 1;
                  return (
                    <DDTSubColumnHeader
                      key={col.id}
                      isLast={isLastCol}
                      style={{
                        flex: col.width ? `0 0 ${col.width}` : 1,
                        width: col.width || 'auto',
                      }}
                      role="columnheader"
                      data-testid={testId(`subcolumn-header-${col.id}`)}
                    >
                      {col.title}
                      <InfoIcon tooltip={col.tooltipContent} />
                    </DDTSubColumnHeader>
                  );
                })}
              </DDTSubColumnsRow>
            </DDTGroupHeader>
          );
        })}
      </DDTGroupsWrapper>
    </DDTHeaderRow>
  );
};
